-- More linked UofT Engineering questions: the existing analytical and
-- experiment-design questions (both UofT Q3 banks), each with a changed or
-- added condition for question 3. Questions already in the linked pool are skipped.
insert into public.mock_interview_bank_questions (bank_id, title, question_type, follow_ups, follow_up_linked, follow_up_prep, follow_up_response, sort_order)
select '7c1d2e3f-4a5b-4c6d-8e9f-0a1b2c3d4e5f', v.title, 'video', v.fu, true, 30, 180, v.n
from (values
  ('List 3 factors you need to know if you want to calculate the mass of a 70-floor building. How would you use them?', '[["Now suppose the building is a timber skyscraper made mostly of engineered wood instead of concrete and steel. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 41),
  ('List 3 factors you need to know if you want to calculate the number of primary schools in a city with a population of 5 million.', '[["Now suppose the government lowers the maximum class size from 30 to 20 students. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 42),
  ('List 3 factors you need to know if you want to calculate the market size for a coffee shop in a city with a population of 5 million.', '[["Now suppose a large international coffee chain opens 50 new stores in the same city. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 43),
  ('Xiao Ming is visiting 10 cities to sell his products. List 3 factors you need to know to calculate the shortest route.', '[["Now suppose two of the cities can only be reached by ferry, which leaves twice a day. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 44),
  ('List 3 factors you need to know if you want to calculate the volume of a 2-floor shopping centre.', '[["Now suppose the shopping centre has an indoor atrium that is open from the ground floor to the roof. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 45),
  ('List 3 factors you need to know to calculate the number of gas stations in a city with a population of 5 million.', '[["Now suppose 40% of the cars in the city are electric. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 46),
  ('List 3 factors you need to know to calculate the shortest time to finish painting 50 drawings with 10 staff.', '[["Now suppose each drawing has to dry for one hour before a second layer of paint can be added. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 47),
  ('List 3 factors you need to know to calculate the shortest time to transport 100 people to the other side of a river with a boat that can carry up to 500 kg of people.', '[["Now suppose the river has a strong current and the boat can only cross while the current is weak. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 48),
  ('You are asked to determine the amount of fuel required to drive a truck carrying cargo twice as heavy as your previous trip. You will be driving the same distance as your previous trip under similar conditions. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the return trip is uphill, against a strong headwind. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 49),
  ('You want to determine if a new material created for solar panels increases the amount of energy that can be captured. You have acquired 15 panels of different sizes, manufactured with different materials including the new material. You decide to set up an experiment to solve this problem. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the panels must be tested outdoors over several weeks instead of in a lab. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 50),
  ('You want to determine if the flow rate of a semi-solid material through a pipe alters the composition of the semi-solid material. You have access to six different facilities that use different standard flow rates in their manufacturing process. You decide to set up an experiment to solve this problem. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose only two of the six facilities agree to let you take samples. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 51),
  ('You are asked to determine the volume of a sewage digestion tank required to accommodate inflow and outflow rates that are three times that of the previous process. A digestion tank is a container that holds liquid for a period of time as it gets processed. What do you think are the THREE most important variables to address? How would you incorporate those variables in your solution?', '[["Now suppose the inflow is not steady: most of it arrives in a few hours each morning. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 52),
  ('You want to determine if the weight of a spherical stone changes the distance the sphere will roll downhill. You happen to see 12 spherical stones of various sizes near a hill. You have a tape measure and a scale. You decide to set up an experiment to solve this problem. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the hill is covered in grass in some places and gravel in others. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 53),
  ('As a soccer coach you oversee a little league beach soccer tournament. For fairness, you want to determine if the weight of a soccer ball changes the distance the ball will roll across a windy beach. You have 16 soccer balls of various sizes, a tape measure, and a scale. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the tournament is moved to a grass field on a calm day. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 54),
  ('As a City of Toronto traffic control engineer you want to determine if the size of vehicles affects the total number of vehicles that can pass through an intersection. You have access to a very large parking lot and 100 cars and trucks of various sizes. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose half of the vehicles are self-driving and can follow each other more closely. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 55),
  ('As a ship''s captain, you are asked to determine the amount of fuel required to move an empty cargo ship to Amsterdam relative to the previous trip when the ship was fully loaded. You will be going the same distance as your previous trip under similar conditions. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the ship has to sail through a winter storm on the way to Amsterdam. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 56),
  ('As a city water quality engineer, you want to determine if a new material created to filter water increases the number of particulates that can be captured (compared to current water filters). You have acquired 10 different filters of different sizes, manufactured with different materials including the new material. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the water source changes from a clear lake to a muddy river after spring floods. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 57),
  ('As a member of the city school board, you are asked to determine how many new biology teachers should be hired over the next ten years to support a rapidly growing population. What do you think are the THREE most important variables to address in your investigation? How would you incorporate those variables in your investigation?', '[["Now suppose the province makes biology a required course for all Grade 11 students. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 58),
  ('A factory must transport 500 boxes using 5 trucks. Each truck has a different capacity and speed. List 3 variables to calculate the shortest total delivery time and explain your reasoning.', '[["Now suppose two of the trucks break down halfway through the day. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 59),
  ('List 3 factors you need to know if you want to calculate the number of pizzas sold in one day in a city with a population of 2 million.', '[["Now suppose a major sports final is played in the city on that day. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 60),
  ('List 3 factors you need to know if you want to arrange 8 cleaners to clean all the classrooms in a 40-room school in the shortest time.', '[["Now suppose the school is in use, so each classroom is only free for one hour. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 61),
  ('List 3 factors you need to know if you want to calculate the number of parking spaces a new shopping mall needs.', '[["Now suppose a new subway station opens right next to the mall. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 62),
  ('List 3 factors you need to know if you want to calculate the total weight of all the books in a public library.', '[["Now suppose the library replaces half of its printed books with e-books. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 63),
  ('List 3 factors you need to know if you want to calculate the shortest time to evacuate 1,000 students from a 4-floor school building.', '[["Now suppose the main staircase is closed for repairs during the evacuation. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 64),
  ('List 3 factors you need to know if you want to calculate how many solar panels are needed to power a house for one day.', '[["Now suppose the house adds an electric car that is charged at home every night. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 65),
  ('List 3 factors you need to know if you want to calculate the number of trees needed to make all the paper a high school uses in one year.', '[["Now suppose the school moves all homework and handouts online. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 66),
  ('List 3 factors you need to know if you want to calculate the number of dentists needed in a city with a population of 1 million.', '[["Now suppose the city adds fluoride to its drinking water, which reduces tooth decay. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 67),
  ('List 3 factors you need to know if you want to calculate how much paint is needed to paint all the walls of a 20-floor apartment building.', '[["Now suppose the building has large balconies and many floor-to-ceiling windows. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 68),
  ('List 3 factors you need to know if you want to calculate how much electricity a school uses in one year.', '[["Now suppose the school installs solar panels on its roof and switches to LED lighting. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 69),
  ('A stadium has 50,000 seats and 10 exits. List 3 factors you need to know to calculate the shortest time for all fans to leave after a game.', '[["Now suppose two of the ten exits are closed for construction. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 70),
  ('A bakery wants to bake 2,000 loaves of bread for a festival using 4 ovens. List 3 factors you need to know to calculate the shortest baking time.', '[["Now suppose one of the four ovens can only hold half as many loaves as the others. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 71),
  ('A delivery company must deliver 300 packages in one day using 6 vans. List 3 factors you need to know to plan the routes so that all packages are delivered as early as possible.', '[["Now suppose a snowstorm reduces driving speeds by half in the afternoon. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 72),
  ('A ferry can carry up to 2,000 kg of cars. List 3 factors you need to know to calculate the shortest time to move 50 cars across a lake.', '[["Now suppose the cars are a mix of small cars and heavy pickup trucks. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 73),
  ('A library wants to move 20,000 books to a new building using 3 carts and 5 volunteers. List 3 factors you need to know to calculate the shortest time to finish the move.', '[["Now suppose the new building is on the third floor with only one small elevator. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 74),
  ('You want to determine if the temperature of water changes how fast sugar dissolves in it. You have 10 cups, a kettle, a thermometer, a stopwatch and a bag of sugar. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose you must use the same cup of water for every test and can only heat it once. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 75),
  ('As a school sports coordinator, you want to determine if the type of running shoe affects how fast students run 100 metres. You have 20 pairs of shoes of different brands and sizes and a stopwatch. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the race must be run outdoors on a track, and the weather changes during the day. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 76),
  ('As a city parks engineer, you want to determine if the type of surface under a playground (grass, sand or rubber) changes how high a ball bounces. You have 12 balls of different sizes and a measuring stick. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the test must be done in winter, when the sand and grass may be frozen. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 77),
  ('You want to determine if the colour of a roof affects the temperature inside a house. You have 8 small model houses with roofs of different colours and materials, and several thermometers. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the model houses must be placed outdoors, some in the sun and some in partial shade. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 78),
  ('As a food scientist, you want to determine if storage temperature affects how long fresh strawberries stay edible. You have 5 fridges set at different temperatures and 200 strawberries from different farms. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the strawberries are delivered over three days instead of all at once. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 79),
  ('As a city transportation engineer, you want to determine if adding a bike lane changes the average speed of cars on a street. You have traffic data from 10 streets of different lengths, some with bike lanes and some without. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the city also changes the speed limit on some of the streets during the study. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 80),
  ('You want to determine if the length of a pendulum changes how long it takes to swing back and forth. You have strings of different lengths, metal balls of different weights, and a stopwatch. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the pendulum must swing inside a moving bus. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 81),
  ('As an agricultural engineer, you want to determine if a new fertilizer increases the height of tomato plants. You have 20 tomato plants of different ages, two greenhouses, and the new fertilizer. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose only one greenhouse is available, and it has a sunny side and a shady side. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 82),
  ('You want to determine if the air pressure in a bicycle tire affects how far the bike rolls down a ramp without pedalling. You have 6 bikes of different sizes, a pump with a pressure gauge, and a tape measure. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the ramp has to be built outdoors on a windy day. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 83),
  ('As a phone company engineer, you want to determine if a new phone case reduces screen damage when phones are dropped. You have 15 phones of different models, cases made of different materials including the new one, and a tall ladder. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose you can only drop each phone once, because a damaged phone cannot be reused. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 84),
  ('As a school principal, you want to determine if playing background music in the library changes how long students stay focused on homework. You have 4 study rooms and 60 student volunteers from different grades. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the study runs during exam week, when students are already under more pressure. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 85),
  ('You want to determine if the thickness of ice changes how much weight it can hold. You have ice blocks of different thicknesses and sizes made in a freezer, and a set of weights. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the ice blocks must be tested at room temperature, so they begin to melt during the test. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 86),
  ('As a city water engineer, you want to determine if the size of a pipe changes how much water reaches the top floor of an apartment building. You have pipes of different diameters and materials and access to buildings of different heights. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the buildings'' water pumps run at different pressures. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 87),
  ('You want to determine if the angle of a solar panel changes how much electricity it produces during the day. You have 10 panels from different manufacturers and an adjustable stand. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the test takes place in December in Toronto, when the sun is low in the sky. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 88),
  ('As a sports equipment designer, you want to determine if the weight of a hockey stick affects how fast a player can shoot a puck. You have 12 sticks of different weights and lengths, a radar speed gun, and 5 players of different skill levels. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the shots must be taken outdoors on natural ice, where the ice quality changes during the day. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 89),
  ('As an environmental engineer, you want to determine if planting trees along a busy road reduces the noise heard by nearby homes. You have a sound meter and access to 10 roads with different numbers of trees and different amounts of traffic. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose half of the trees lose their leaves in winter. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 90),
  ('You want to determine which wrapping material keeps a cup of hot chocolate warm the longest. You have cups of different sizes, aluminium foil, cloth, paper, and a thermometer. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the hot chocolate is kept outside on a cold winter day instead of indoors. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 91),
  ('As a city snow-removal engineer, you want to determine if a new de-icing salt melts ice faster than the salt currently used. You have 20 patches of icy sidewalk in different parts of the city, both types of salt, and a stopwatch. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the temperature drops below −15 °C, where some salts stop working. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 92),
  ('As a drone engineer, you want to determine if the number of propellers changes how long a drone can stay in the air. You have 8 drones of different sizes with 2, 4 or 6 propellers, and batteries of different capacities. What do you think are the THREE most important variables to address in your experiment? How would you incorporate those variables in your experiment?', '[["Now suppose the drones must carry a camera that weighs 300 g. How would you change your experiment? Which of your three variables are affected, and would you add or replace any?"]]'::jsonb, 93),
  ('You are asked to determine how much longer it will take to fill a water tank if the pipe filling it is replaced with one that carries half as much water per minute, while water is still being used from the tank. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the water use from the tank doubles at night. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 94),
  ('As a bakery manager, you are asked to determine how many extra staff you need if daily orders triple during the holiday season. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose half of the new orders are custom cakes that take three times longer to make. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 95),
  ('You are asked to determine the amount of electricity needed to charge an electric car for a trip twice as long as your previous trip, under similar driving conditions. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the trip is in winter, and the temperature is −20 °C. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 96),
  ('As a member of the city council, you are asked to determine how many new ambulances the city should buy over the next five years to support a growing and ageing population. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose a new highway cuts the average travel time to the hospital in half. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 97),
  ('As an airline planner, you are asked to determine how much more fuel a plane needs if it carries 50 more passengers than on its previous flight on the same route. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the flight now has a strong headwind for the whole route. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 98),
  ('As a school board planner, you are asked to determine how many new classrooms will be needed in ten years if the number of students in the district keeps growing. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the district switches to a hybrid model where students are in school only three days a week. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 99),
  ('As a restaurant owner, you are asked to determine how much food to order for next week if you expect 40% more customers than this week. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose a heat wave is forecast for next week. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 100),
  ('You are asked to determine how long it will take to cool a classroom to a comfortable temperature if the number of students in the room doubles. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the air conditioner is replaced with one that is 30% more powerful, but the windows face the afternoon sun. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 101),
  ('As a city recycling manager, you are asked to determine how many more recycling trucks are needed if the city switches from collecting recycling every two weeks to every week. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose the city also starts collecting food waste in the same trucks. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 102),
  ('As a hospital manager, you are asked to determine how many more beds are needed if the average patient stay becomes one day longer than last year. What do you think are the THREE most important variables to address to solve this problem? How would you incorporate those variables in your solution?', '[["Now suppose a new clinic opens nearby and takes 20% of the hospital''s patients. How would you re-evaluate the problem? Does your solution change — which of your three factors are affected, and would you add or replace any?"]]'::jsonb, 103)
) as v(title, fu, n)
where not exists (
  select 1 from public.mock_interview_bank_questions b where b.bank_id = '7c1d2e3f-4a5b-4c6d-8e9f-0a1b2c3d4e5f' and lower(b.title) = lower(v.title)
);

update public.mock_interview_questions
   set description = '多伦多大学工程视频面试新题型（练习题，非真题）：第二题是分析/估算题或实验设计题，第三题在第二题基础上改变或增加一个条件，问你如何重新评估（或如何调整实验）、3 个变量是否需要调整。答题思路：先说哪个变量受影响、怎样影响 → 是否要新增或替换变量 → 结论是否改变。'
 where id = '7c1d2e3f-4a5b-4c6d-8e9f-0a1b2c3d4e5f';
